from flask import Flask, render_template
import os

app = Flask(__name__)

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/alibaba')
def alibaba():
    story = "Alibaba Group является эталоном платформенной экономики. Основанная Джеком Ма в 1999 году, компания трансформировала хаотичный рынок мелких китайских производителей в упорядоченную глобальную систему. В отличие от западных аналогов, Alibaba изначально создавалась для решения проблемы 'дефицита доверия' в условиях развивающейся экономики. Ключевым фактором стала модель 'Asset-light' и система верификации TrustPass. На сегодняшний день успех Alibaba обеспечен применением алгоритмов анализа данных, которые позволяют предсказывать спрос на оптовом уровне и оптимизировать логистику через Cainiao. В дополнение к вышеупомянутым технологическим решениям, стратегическое доминирование Alibaba Group на современном этапе обусловлено интеграцией концепции «New Retail», стирающей границы между онлайн-коммерцией и физическими точками продаж. Данная экосистема опирается на облачную инфраструктуру Alibaba Cloud, которая обеспечивает бесперебойную обработку транзакционных массивов (Big Data) в периоды пиковых нагрузок, сопоставимых по масштабу с глобальными дисконтными событиями уровня «Double 11». Масштабирование операционной деятельности корпорации также неразрывно связано с развитием финтех-подразделения Ant Group (Alipay). Внедрение систем скоринга на базе искусственного интеллекта позволило радикально снизить барьеры входа для субъектов малого и среднего предпринимательства (SME), предоставив им доступ к трансграничным платежам и микрофинансированию. Таким образом, Alibaba эволюционировала из классического маркетплейса в комплексную цифровую инфраструктуру, которая детерминирует стандарты глобальной электронной торговли. Дальнейшее укрепление позиций компании на международных рынках, в частности через платформы AliExpress и Lazada, напрямую коррелирует с инвестициями в автономные логистические системы и роботизированные распределительные центры. Это позволяет минимизировать операционные издержки и сократить сроки доставки в рамках инициативы «Global 72-hour delivery», закрепляя за Alibaba статус ключевого архитектора современной цифровой экономики."
    return render_template('project.html', title="Alibaba Group: Протоколы экосистем B2B", mode="Business-to-Business (B2B)", story=story)

@app.route('/amazon')
def amazon():
    story = "Amazon прошел путь от нишевого онлайн-магазина до доминирующей технологической корпорации. Стратегия Джеффа Безоса базировалась на 'радикальной долгосрочности' и фанатичном стремлении к удобству клиента. Центральным элементом успеха Amazon является концепция 'Маховика' (Flywheel), где снижение цен ведет к росту посещаемости, что привлекает сторонних продавцов. Роботизированные фулфилмент-центры и подписка Prime создали психологическую привязанность клиента к платформе, превратив покупку в один клик в стандарт мировой торговли. Фундаментальным аспектом устойчивости бизнес-модели Amazon является вертикальная интеграция её технологического стека, где подразделение Amazon Web Services (AWS) выступает не только в роли основного генератора операционной прибыли, но и в качестве инфраструктурного базиса для функционирования всей ритейл-экосистемы. Высокая маржинальность облачных вычислений позволяет корпорации субсидировать капиталоемкие проекты в сфере логистики и робототехники, поддерживая агрессивную экспансию на новые рынки. В контексте операционной эффективности ключевую роль играет внедрение систем машинного обучения (Machine Learning) в управление складскими запасами и прогнозирование потребительского поведения. Развитие инфраструктуры Amazon Robotics позволило оптимизировать время обработки заказов в фулфилмент-центрах (FC), снизив удельные издержки на единицу товара и повысив пропускную способность распределительной сети. Параллельно с этим компания консолидирует свои позиции в сфере цифровых медиа и рекламных технологий (Amazon Advertising), используя массив данных о покупках для создания таргетированных каналов коммуникации. Эта стратегия замыкает цикл взаимодействия с клиентом внутри единой инфраструктуры, создавая значительные барьеры для входа конкурентов. Дополнительным вектором развития выступает интеграция в сферу здравоохранения (Amazon Pharmacy) и офлайн-ритейла (Whole Foods Market, Amazon Go). Применение технологий компьютерного зрения «Just Walk Out» в физических точках продаж детерминирует новые стандарты сервиса, подтверждая статус Amazon как лидера технологической трансформации традиционных отраслей экономики в глобальном масштабе."
    return render_template('project.html', title="Amazon: Гигант Розничных Продаж", mode="Business-to-Consumer (B2C)", story=story)

if __name__ == "__main__":
    port = int(os.environ.get("PORT", 5000))
    app.run(host='0.0.0.0', port=port)
